<script setup lang="ts">
import { ref, watch } from "vue";
import { type CheckoutTransientConflictMode, type PurchaseCheckoutPolicy } from "@papilio/api";
import NumField from "@papilio/ui/NumField.vue";
const props=defineProps<{modelValue:PurchaseCheckoutPolicy|null;transientModes?:CheckoutTransientConflictMode[]}>();
const emit=defineEmits<{"update:modelValue":[value:PurchaseCheckoutPolicy];valid:[value:boolean]}>();
const expiry=ref(""),enabled=ref(false),admission=ref<PurchaseCheckoutPolicy["admission_mode"]>("require_ready_bundle");
const recovery=ref<CheckoutTransientConflictMode>("retry_until_expiry");
const recoveryLabels:Record<CheckoutTransientConflictMode,string>={retry_until_expiry:"Retry automatically until checkout expires",require_confirmation:"Ask the customer to confirm before retrying"};
watch(()=>props.modelValue,value=>{expiry.value=value?String(value.default_expiry_seconds):"";enabled.value=value?.enabled??false;admission.value=value?.admission_mode??"require_ready_bundle";recovery.value=value?.transient_conflict_action??"retry_until_expiry";},{immediate:true});
watch([expiry,enabled,()=>props.modelValue],()=>emit("valid",(!props.modelValue&&!enabled.value&&!expiry.value)||(Number.isSafeInteger(Number(expiry.value))&&Number(expiry.value)>0)),{immediate:true});
function apply():void{const seconds=Number(expiry.value);if(!Number.isSafeInteger(seconds)||seconds<=0)return;emit("update:modelValue",{enabled:enabled.value,admission_mode:admission.value,default_expiry_seconds:seconds,...(props.transientModes?.includes(recovery.value)?{transient_conflict_action:recovery.value}:{})});}
</script>
<template><section class="form-grid" aria-label="Automated purchase policy"><h3>Automated purchase policy</h3><p>Payment approval can fund a selected plan. Ambiguous payments remain under review; failed provisioning follows the saved refund policy.</p><p v-if="!modelValue">No explicit policy is saved. Enter its lifetime and apply the draft before saving settings.</p><label class="check-row"><input v-model="enabled" type="checkbox" @change="apply" />Enable automated checkout</label><label class="field"><span>Plan delivery requirement</span><select v-model="admission" @change="apply"><option value="require_ready_bundle">Require an available configuration bundle</option><option value="allow_manual_profiles">Also allow plans awaiting manual configuration</option></select></label><label v-if="transientModes?.length" class="field"><span>When connection inventory is temporarily busy</span><select v-model="recovery" aria-label="Transient checkout conflict policy" @change="apply"><option v-for="mode in transientModes" :key="mode" :value="mode">{{recoveryLabels[mode]}}</option></select><small>Automatic retries keep the saved offer and stop at its deadline. A changed plan or price still follows the customer’s review decision.</small></label><NumField v-model="expiry" label="Checkout lifetime (seconds)" @update:model-value="apply" /><button type="button" class="btn secondary" :disabled="!Number.isSafeInteger(Number(expiry))||Number(expiry)<=0" @click="apply">Apply purchase policy draft</button></section></template>
